steps.expression:
// A streamed answer comes as Reader; an ordinary one is already in Content.
var reader = #Previous.Reader;
var rest = new Queue<string>((#Previous.Content ?? "").Split('\n'));
Func<string> next = () => reader != null ? reader.ReadLine()
                        : rest.Count > 0 ? rest.Dequeue() : null;
int sent = 0;
for (var line = next(); line != null; line = next())
{
    if (string.IsNullOrWhiteSpace(line)) continue;   // separators, not chunks
    Action.BoundaryEvents["Event_Chunk"].Raise(line); // out as it lands
    sent++;
}
reader?.Dispose();
Logger.LogInformation($"{sent} chunks passed on for {Input.topic}");
return new StreamRequest() { topic = Input.topic };

